// ======================================================================
// \title  SimLinkTester.hpp
// \author my-flight-sim
// \brief  hpp file for SimLink component test harness implementation class
//
// The base class SimLinkGTestBase is generated by FPP from SimLink.fpp. It
// gives us invoke_to_<port>() functions to call the component's input ports,
// records everything the component sends on its output ports, events and
// telemetry, and provides ASSERT_* macros to check those histories.
// ======================================================================

#ifndef MyFlightSim_SimLinkTester_HPP
#define MyFlightSim_SimLinkTester_HPP

#include "MyFlightSim/Components/SimLink/SimLink.hpp"
#include "MyFlightSim/Components/SimLink/SimLinkGTestBase.hpp"

namespace MyFlightSim {

class SimLinkTester final : public SimLinkGTestBase {
  public:
    // ----------------------------------------------------------------------
    // Constants
    // ----------------------------------------------------------------------

    // Maximum size of histories storing events, telemetry, and port outputs
    static const FwSizeType MAX_HISTORY_SIZE = 10;

    // Instance ID supplied to the component instance under test
    static const FwEnumStoreType TEST_INSTANCE_ID = 0;

  public:
    // ----------------------------------------------------------------------
    // Construction and destruction
    // ----------------------------------------------------------------------

    //! Construct object SimLinkTester
    SimLinkTester();

    //! Destroy object SimLinkTester
    ~SimLinkTester();

  public:
    // ----------------------------------------------------------------------
    // Tests
    // ----------------------------------------------------------------------

    //! Consecutive valid frames each produce exactly one clock tick
    void testValidFramesDriveClock();

    //! A datagram with the wrong magic number is rejected and does not tick
    void testBadMagicRejected();

    //! A datagram too short to hold a header is rejected and does not tick
    void testShortDatagramRejected();

    //! A gap in tick numbers is reported, and the clock still ticks
    void testMissedTicksReported();

    //! A receive error from the driver is ignored, but the buffer is returned
    void testDriverErrorIgnored();

    //! A tick number going backwards is treated as a simulator restart
    void testSimulatorRestart();

  private:
    // ----------------------------------------------------------------------
    // Helper functions
    // ----------------------------------------------------------------------

    //! Connect ports
    void connectPorts();

    //! Initialize components
    void initComponents();

    //! Build a datagram holding a serialized SimHeader in m_data
    Fw::Buffer makeFrame(U32 magic, U32 tick, U64 simTimeUs);

    //! Send one datagram into the component as if the Udp driver received it
    void receive(Fw::Buffer& buffer, Drv::ByteStreamStatus status = Drv::ByteStreamStatus::OP_OK);

  private:
    // ----------------------------------------------------------------------
    // Member variables
    // ----------------------------------------------------------------------

    //! The component under test
    SimLink component;

    //! Backing memory for test datagrams
    U8 m_data[64];
};

}  // namespace MyFlightSim

#endif
